        url_fseek(pb, size + nsv->nsvf_index_data[i], SEEK_SET);

        get_buffer(pb, b, 8);

        PRINT(("NSV [0x%08lx][0x%08lx]: %02x %02x %02x %02x %02x %02x %02x %02x"

