                            float *prediction_error, float energy_mean,

                            const float *pred_table)

{

    // Equations 66-69:

    // ^g_c = ^gamma_gc * 100.05 (predicted dB + mean dB - dB of fixed vector)

    // Note 10^(0.05 * -10log(average x2)) = 1/sqrt((average x2)).

