        ff_set_mpeg4_time(s, s->picture_number); 
                    ff_estimate_b_frame_motion(s, mb_x, mb_y);
                    ff_estimate_p_frame_motion(s, mb_x, mb_y);
    }else if(s->pict_type == I_TYPE){
