void ff_vdpau_h264_picture_complete(MpegEncContext *s)

{

    H264Context *h = s->avctx->priv_data;

    struct vdpau_render_state *render;

    int i;



    render = (struct vdpau_render_state *)s->current_picture_ptr->data[0];

    assert(render);



