    if (uptr != NULL) {

        if ((vptr > val) && (len > 0) &&

	    (uptr[0] == '/') && (vptr[-1] == '/')) {

	    memcpy (vptr, uptr + 1, len - 1);

	    vptr[len - 2] = 0;

	} else {

	    memcpy (vptr, uptr, len);

	    vptr[len - 1] = 0;

	}

    } else {

	vptr[len - 1] = 0;

