        if (env->active_fpu.fcr0 & (1 << FCR0_F64))

            env->hflags |= MIPS_HFLAG_F64;

#endif

    }

}

udp_listen(port, laddr, lport, flags)

	u_int port;

	u_int32_t laddr;

	u_int lport;

	int flags;

{

	struct sockaddr_in addr;

	struct socket *so;

	int addrlen = sizeof(struct sockaddr_in), opt = 1;



	if ((so = socreate()) == NULL) {

		free(so);

		return NULL;

	}

	so->s = socket(AF_INET,SOCK_DGRAM,0);

