av_cold int sws_init_context(SwsContext *c, SwsFilter *srcFilter,

                             SwsFilter *dstFilter)

{

    int i;

    int usesVFilter, usesHFilter;

    int unscaled;

    SwsFilter dummyFilter = { NULL, NULL, NULL, NULL };

    int srcW              = c->srcW;

    int srcH              = c->srcH;

    int dstW              = c->dstW;

    int dstH              = c->dstH;

    int dst_stride        = FFALIGN(dstW * sizeof(int16_t) + 16, 16);

    int dst_stride_px     = dst_stride >> 1;

    int flags, cpu_flags;

    enum PixelFormat srcFormat = c->srcFormat;

    enum PixelFormat dstFormat = c->dstFormat;



    cpu_flags = av_get_cpu_flags();

    flags     = c->flags;

    emms_c();

    if (!rgb15to16)

        sws_rgb2rgb_init();



    unscaled = (srcW == dstW && srcH == dstH);



    if (!sws_isSupportedInput(srcFormat)) {

        av_log(c, AV_LOG_ERROR, "%s is not supported as input pixel format\n",

               sws_format_name(srcFormat));

        return AVERROR(EINVAL);

    }

    if (!sws_isSupportedOutput(dstFormat)) {

        av_log(c, AV_LOG_ERROR, "%s is not supported as output pixel format\n",

               sws_format_name(dstFormat));

        return AVERROR(EINVAL);

    }



    i = flags & (SWS_POINT         |

                 SWS_AREA          |

                 SWS_BILINEAR      |

                 SWS_FAST_BILINEAR |

                 SWS_BICUBIC       |

                 SWS_X             |

                 SWS_GAUSS         |

                 SWS_LANCZOS       |

                 SWS_SINC          |

                 SWS_SPLINE        |

                 SWS_BICUBLIN);

    if (!i || (i & (i - 1))) {

        av_log(c, AV_LOG_ERROR,

               "Exactly one scaler algorithm must be chosen\n");

        return AVERROR(EINVAL);

    }

    /* sanity check */

    if (srcW < 4 || srcH < 1 || dstW < 8 || dstH < 1) {

        /* FIXME check if these are enough and try to lower them after

         * fixing the relevant parts of the code */

        av_log(c, AV_LOG_ERROR, "%dx%d -> %dx%d is invalid scaling dimension\n",

               srcW, srcH, dstW, dstH);

        return AVERROR(EINVAL);

    }



    if (!dstFilter)

        dstFilter = &dummyFilter;

    if (!srcFilter)

        srcFilter = &dummyFilter;



    c->lumXInc      = (((int64_t)srcW << 16) + (dstW >> 1)) / dstW;

    c->lumYInc      = (((int64_t)srcH << 16) + (dstH >> 1)) / dstH;

    c->dstFormatBpp = av_get_bits_per_pixel(&av_pix_fmt_descriptors[dstFormat]);

    c->srcFormatBpp = av_get_bits_per_pixel(&av_pix_fmt_descriptors[srcFormat]);

    c->vRounder     = 4 * 0x0001000100010001ULL;



    usesVFilter = (srcFilter->lumV && srcFilter->lumV->length > 1) ||

                  (srcFilter->chrV && srcFilter->chrV->length > 1) ||

                  (dstFilter->lumV && dstFilter->lumV->length > 1) ||

                  (dstFilter->chrV && dstFilter->chrV->length > 1);

    usesHFilter = (srcFilter->lumH && srcFilter->lumH->length > 1) ||

                  (srcFilter->chrH && srcFilter->chrH->length > 1) ||

                  (dstFilter->lumH && dstFilter->lumH->length > 1) ||

                  (dstFilter->chrH && dstFilter->chrH->length > 1);



    getSubSampleFactors(&c->chrSrcHSubSample, &c->chrSrcVSubSample, srcFormat);

    getSubSampleFactors(&c->chrDstHSubSample, &c->chrDstVSubSample, dstFormat);



    /* reuse chroma for 2 pixels RGB/BGR unless user wants full

     * chroma interpolation */

    if (flags & SWS_FULL_CHR_H_INT &&

        isAnyRGB(dstFormat)        &&

        dstFormat != PIX_FMT_RGBA  &&

        dstFormat != PIX_FMT_ARGB  &&

        dstFormat != PIX_FMT_BGRA  &&

        dstFormat != PIX_FMT_ABGR  &&

        dstFormat != PIX_FMT_RGB24 &&

        dstFormat != PIX_FMT_BGR24) {

        av_log(c, AV_LOG_ERROR,

               "full chroma interpolation for destination format '%s' not yet implemented\n",

               sws_format_name(dstFormat));

        flags   &= ~SWS_FULL_CHR_H_INT;

        c->flags = flags;

    }

    if (isAnyRGB(dstFormat) && !(flags & SWS_FULL_CHR_H_INT))

        c->chrDstHSubSample = 1;



    // drop some chroma lines if the user wants it

    c->vChrDrop          = (flags & SWS_SRC_V_CHR_DROP_MASK) >>

                           SWS_SRC_V_CHR_DROP_SHIFT;

    c->chrSrcVSubSample += c->vChrDrop;



    /* drop every other pixel for chroma calculation unless user

     * wants full chroma */

    if (isAnyRGB(srcFormat) && !(flags & SWS_FULL_CHR_H_INP)   &&

        srcFormat != PIX_FMT_RGB8 && srcFormat != PIX_FMT_BGR8 &&

        srcFormat != PIX_FMT_RGB4 && srcFormat != PIX_FMT_BGR4 &&

        srcFormat != PIX_FMT_RGB4_BYTE && srcFormat != PIX_FMT_BGR4_BYTE &&

        ((dstW >> c->chrDstHSubSample) <= (srcW >> 1) ||

         (flags & SWS_FAST_BILINEAR)))

