                                  (src[0]         << 12) |

                                 ((src[2] & 0x0F) <<  8) |

                                   src[1];

                // extract high 20 bits and expand to 32 bits

                *dst_int32_t++ =  (src[4]         << 24) |

                                  (src[3]         << 16) |

                                 ((src[2] & 0xF0) <<  8) |

                                  (src[4]         <<  4) |

                                  (src[3]         >>  4);

                src += 5;

            }

        }

        break;

    }

    default:

        return -1;

    }



    *got_frame_ptr   = 1;

    *(AVFrame *)data = s->frame;



    return buf_size;

}

